CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `pagos_realizado`  AS SELECT `t_detalle`.`nt` AS `numero_tramite`, `anio_nt`.`anio_nt` AS `anio_numerotramite`, `t_detalle`.`nombre_solicitante` AS `solicitante`, `t_detalle`.`nombre_apoderado` AS `apoderado`, sum(`t_detalle`.`importe_devolucion_unfv`) AS `monto_voucher`, `banco`.`nombre_banco` AS `nombre_banco`, `t_detalle`.`nro_cuenta_banco` AS `nro_cuenta_banco`, `concepto`.`nombre` AS `nombre_concepto` FROM (((`tb_detalle_devolucion` `t_detalle` join `tb_bancos` `banco` on(`banco`.`id_banco` = `t_detalle`.`id_banco`)) join `tb_conceptos` `concepto` on(`concepto`.`id_concepto` = `t_detalle`.`id_concepto`)) join `tb_anio_nt` `anio_nt` on(`anio_nt`.`id_anio_nt` = `t_detalle`.`id_anio_nt`)) WHERE `t_detalle`.`visible` <> 1 GROUP BY `t_detalle`.`nombre_solicitante`, `t_detalle`.`nt` ;

